from pathlib import Path
from html.parser import HTMLParser
import hashlib, json, re

class TextBlocks(HTMLParser):
    blocks = {'p', 'li', 'h1', 'h2', 'h3', 'h4', 'td', 'th'}
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.open_blocks = []
        self.items = []
        self.ignored = 0
    def handle_starttag(self, tag, attrs):
        if tag in {'script', 'style'}:
            self.ignored += 1
        if not self.ignored and tag in self.blocks:
            self.open_blocks.append((tag, []))
    def handle_data(self, data):
        if not self.ignored:
            for _, parts in self.open_blocks:
                parts.append(data)
    def handle_endtag(self, tag):
        if tag in {'script', 'style'}:
            self.ignored = max(0, self.ignored - 1)
        if self.ignored or tag not in self.blocks:
            return
        for i in range(len(self.open_blocks) - 1, -1, -1):
            if self.open_blocks[i][0] == tag:
                _, parts = self.open_blocks.pop(i)
                line = ' '.join(''.join(parts).split())
                if line:
                    self.items.append(line)
                break

base = Path('products/services/sqlite-lemon-squeezy-seller-fit')
sources = {
    'prohibited-products': ('https://docs.lemonsqueezy.com/help/getting-started/prohibited-products', 'f99f2ee28e73fa837df15f8025d10bbe898a535212202448b2b297f7376ae518'),
    'fees': ('https://docs.lemonsqueezy.com/help/getting-started/fees', 'db5842dd40885829ba573a34af6676af15121d0786249ce88592273b69090bc2'),
    'supported-countries': ('https://docs.lemonsqueezy.com/help/getting-started/supported-countries', '6ce6b7b842d73f214a5088674844d4d6dbd24a353c1dd1dc51a52792fc759616'),
}
pattern = re.compile(r'prohibit|copyright|licen[cs]|third.party|\bAI\b|artificial intelligence|software|digital|approv|activat|Canada|fee|payout|minimum|threshold|international|PayPal|\$50', re.I)
report = {'purpose': 'Reading aid. Absence of a passage does not establish eligibility, fee coverage, or payout terms.', 'sources': {}}
for name, (url, expected) in sources.items():
    raw = (base / 'raw' / (name + '.html')).read_bytes()
    sha = hashlib.sha256(raw).hexdigest()
    if sha != expected:
        raise ValueError(f'{name}: source hash differs from retrieval receipt')
    parser = TextBlocks()
    parser.feed(raw.decode('utf-8'))
    blocks = list(dict.fromkeys(parser.items))
    matched = [{'index': i, 'text': block} for i, block in enumerate(blocks) if pattern.search(block)]
    report['sources'][name] = {'url': url, 'sha256': sha, 'blocks_parsed': len(blocks), 'matches': matched}
out = base / 'director-product-policy-passages.json'
out.write_text(json.dumps(report, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({name: len(entry['matches']) for name, entry in report['sources'].items()}))
